-- PostgreSQL schema generated from supplied MariaDB dump. Review before production use.

CREATE TABLE IF NOT EXISTS "cms_admins" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "username" VARCHAR(100) NOT NULL,
  "password_hash" VARCHAR(255) NOT NULL,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("id"),
  CONSTRAINT "cms_admins_username_key" UNIQUE ("username")
);

CREATE TABLE IF NOT EXISTS "cms_content" (
  "content_key" VARCHAR(150) NOT NULL,
  "content_value" TEXT NOT NULL,
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("content_key")
);

CREATE TABLE IF NOT EXISTS "cms_fiverr_orders" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" VARCHAR(100) NOT NULL,
  "client_username" VARCHAR(150) NOT NULL,
  "project_title" VARCHAR(255) NOT NULL,
  "category" VARCHAR(100) NOT NULL DEFAULT 'General',
  "amount" NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  "fiverr_fee" NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  "start_date" DATE DEFAULT NULL,
  "deadline" TIMESTAMP DEFAULT NULL,
  "status" VARCHAR(30) NOT NULL DEFAULT 'Pending',
  "progress" SMALLINT  NOT NULL DEFAULT 0,
  "order_url" VARCHAR(500) NOT NULL DEFAULT '',
  "notes" TEXT DEFAULT NULL,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "client_company" VARCHAR(255) NOT NULL DEFAULT '',
  "profile_name" VARCHAR(150) NOT NULL DEFAULT '',
  "category_id" VARCHAR(40) NOT NULL DEFAULT '',
  "message_type" VARCHAR(80) NOT NULL DEFAULT '',
  "message_type_id" VARCHAR(40) NOT NULL DEFAULT '',
  "lead_status" VARCHAR(80) NOT NULL DEFAULT '',
  "lead_status_id" VARCHAR(40) NOT NULL DEFAULT '',
  "quotation_amount" NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  "order_type" VARCHAR(40) NOT NULL DEFAULT '',
  "lead_date" DATE DEFAULT NULL,
  "sales_order_number" VARCHAR(100) NOT NULL DEFAULT '',
  "gross_amount" NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  "net_amount" NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  "sales_id" VARCHAR(100) DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_order_id" UNIQUE ("order_id"),
  CONSTRAINT "unique_sales_id" UNIQUE ("sales_id")
);
CREATE INDEX IF NOT EXISTS "idx_deadline" ON "cms_fiverr_orders" ("deadline");
CREATE INDEX IF NOT EXISTS "idx_status" ON "cms_fiverr_orders" ("status");

CREATE TABLE IF NOT EXISTS "cms_fiverr_profiles" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "username" VARCHAR(150) NOT NULL,
  "created_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("id"),
  CONSTRAINT "cms_fiverr_profiles_username_key" UNIQUE ("username")
);

CREATE TABLE IF NOT EXISTS "cms_fv_mp_audit" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "actor" VARCHAR(150) NOT NULL,
  "event_type" VARCHAR(50) NOT NULL,
  "event_details" TEXT DEFAULT NULL,
  "created_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "cms_fv_mp_audit_created_at" ON "cms_fv_mp_audit" ("created_at");

CREATE TABLE IF NOT EXISTS "cms_fv_mp_commission" (
  "salesperson" VARCHAR(150) NOT NULL,
  "rate_percent" NUMERIC(5,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY ("salesperson")
);

CREATE TABLE IF NOT EXISTS "cms_fv_mp_expenses" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "spent_on" DATE NOT NULL,
  "description" VARCHAR(255) NOT NULL,
  "amount" NUMERIC(14,2) NOT NULL,
  "created_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "cms_fv_mp_expenses_spent_on" ON "cms_fv_mp_expenses" ("spent_on");

CREATE TABLE IF NOT EXISTS "cms_fv_mp_goals" (
  "month_key" CHAR(7) NOT NULL,
  "monthly_target" NUMERIC(14,2) NOT NULL DEFAULT 0.00,
  "daily_target" NUMERIC(14,2) NOT NULL DEFAULT 0.00,
  "updated_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("month_key")
);

CREATE TABLE IF NOT EXISTS "cms_fv_mp_month_close" (
  "month_key" CHAR(7) NOT NULL,
  "order_count" INTEGER NOT NULL,
  "sales_total" NUMERIC(14,2) NOT NULL,
  "snapshot_hash" CHAR(64) NOT NULL,
  "closed_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("month_key")
);

CREATE TABLE IF NOT EXISTS "cms_fv_mp_preferences" (
  "user_key" VARCHAR(100) NOT NULL,
  "widgets_json" TEXT NOT NULL,
  "updated_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("user_key")
);

CREATE TABLE IF NOT EXISTS "cms_fv_notification_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "event_key" VARCHAR(190) NOT NULL,
  "sent_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("id"),
  CONSTRAINT "event_key" UNIQUE ("event_key")
);

CREATE TABLE IF NOT EXISTS "cms_fv_order_history" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_row_id" INTEGER  DEFAULT NULL,
  "sales_id" VARCHAR(100) NOT NULL,
  "action_type" VARCHAR(20) NOT NULL,
  "snapshot_json" TEXT NOT NULL,
  "recorded_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "cms_fv_order_history_recorded_at" ON "cms_fv_order_history" ("recorded_at");
CREATE INDEX IF NOT EXISTS "cms_fv_order_history_sales_id" ON "cms_fv_order_history" ("sales_id");

CREATE TABLE IF NOT EXISTS "cms_fv_person_targets" (
  "month_key" CHAR(7) NOT NULL,
  "salesperson" VARCHAR(150) NOT NULL,
  "target_amount" NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY ("month_key", "salesperson")
);

CREATE TABLE IF NOT EXISTS "cms_fv_security_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "event_type" VARCHAR(60) NOT NULL,
  "actor" VARCHAR(150) NOT NULL DEFAULT '',
  "ip_hash" CHAR(64) NOT NULL DEFAULT '',
  "created_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "cms_fv_security_log_created_at" ON "cms_fv_security_log" ("created_at");

CREATE TABLE IF NOT EXISTS "cms_fv_sync_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "synced_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  "added" INTEGER NOT NULL DEFAULT 0,
  "updated" INTEGER NOT NULL DEFAULT 0,
  "deleted" INTEGER NOT NULL DEFAULT 0,
  "unchanged" INTEGER NOT NULL DEFAULT 0,
  "total" INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "cms_fv_sync_log_synced_at" ON "cms_fv_sync_log" ("synced_at");

CREATE TABLE IF NOT EXISTS "cms_fv_targets" (
  "month_key" CHAR(7) NOT NULL,
  "target_amount" NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  "updated_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("month_key")
);

CREATE TABLE IF NOT EXISTS "cms_items" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "module" VARCHAR(32) NOT NULL,
  "title" VARCHAR(255) NOT NULL,
  "description" TEXT NOT NULL,
  "subtitle" VARCHAR(255) NOT NULL DEFAULT '',
  "image_path" VARCHAR(500) NOT NULL DEFAULT '',
  "link_url" VARCHAR(500) NOT NULL DEFAULT '',
  "sort_order" INTEGER NOT NULL DEFAULT 0,
  "is_published" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "cms_items_module_order" ON "cms_items" ("module", "sort_order", "id");

CREATE TABLE IF NOT EXISTS "cms_messages" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" VARCHAR(120) NOT NULL,
  "email" VARCHAR(255) NOT NULL,
  "service" VARCHAR(120) NOT NULL,
  "message" TEXT NOT NULL,
  "is_read" BOOLEAN NOT NULL DEFAULT FALSE,
  "created_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "cms_private_settings" (
  "setting_key" VARCHAR(80) NOT NULL,
  "setting_value" TEXT NOT NULL,
  PRIMARY KEY ("setting_key")
);

CREATE TABLE IF NOT EXISTS "cms_private_templates" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "title" VARCHAR(200) NOT NULL,
  "category" VARCHAR(100) NOT NULL DEFAULT 'General',
  "body" TEXT NOT NULL,
  "created_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  "updated_at" TIMESTAMPTZ NULL DEFAULT NOW(),
  PRIMARY KEY ("id")
);
